	// role="button" -- and aria-selected is only valid on gridcell/option/row/tab/treeitem.
	// The selected state is already carried by aria-pressed on the same cell, so dropping
	// aria-selected is lossless for AT users and clears axe's aria-allowed-attr rule.
	function installCalendarAriaFix(root) {
		if (window.__amEventsCalendarAriaFixInstalled) return;
		window.__amEventsCalendarAriaFixInstalled = true;
		var target = root && root.querySelectorAll ? root : (document.body || document.documentElement);
		var strip = function () {
			var tds = target.querySelectorAll('td.day[aria-selected]');
			for (var i = 0; i < tds.length; i++) tds[i].removeAttribute('aria-selected');
		};
		strip();
		if (window.MutationObserver) {
			var scheduled = false;
			var flush = function () {
				scheduled = false;
				strip();
			};
			var schedule = function () {
				if (scheduled) return;
				scheduled = true;
				if (window.requestAnimationFrame) {
					window.requestAnimationFrame(flush);
					return;
				}
				window.setTimeout(flush, 0);
			};
			var obs = new MutationObserver(schedule);
			obs.observe(target, { childList: true, subtree: true });
		}
	}

